export function buildExternal(original){
 const {zJoin,boreRadius,flareHeight,flangeHeight,flangeRadius,hexAcrossFlats,hexLength}=dims;
 const lowerBox=()=>r.makeBox([-50,-50,-50],[50,50,zJoin]);
 const originalBase=original.clone().intersect(lowerBox());
 const base=originalBase.clone().cut(r.makeCylinder(boreRadius,zJoin+4.3,[0,0,-4.3]));
 const flare=r.drawCircle(3.999996).sketchOnPlane('XY',zJoin).loftWith(r.drawCircle(flangeRadius).sketchOnPlane('XY',zJoin+flareHeight));
 const flange=r.makeCylinder(flangeRadius,flangeHeight,[0,0,zJoin+flareHeight]);
 const zHex=zJoin+flareHeight+flangeHeight,zTip=zHex+hexLength;
